import React, { useEffect, useState } from 'react';

const API = '/api/products';

export default function App() {
  const [products, setProducts] = useState([]);
  const [form, setForm] = useState({ name: '', sku: '', quantity: '', location: '' });
  const [editId, setEditId] = useState(null);

  const fetchProducts = () =>
    fetch(API).then(r => r.json()).then(setProducts);

  useEffect(() => { fetchProducts(); }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    const method = editId ? 'PUT' : 'POST';
    const url = editId ? `${API}/${editId}` : API;
    await fetch(url, {
      method,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ ...form, quantity: Number(form.quantity) }),
    });
    setForm({ name: '', sku: '', quantity: '', location: '' });
    setEditId(null);
    fetchProducts();
  };

  const handleEdit = (p) => {
    setForm({ name: p.name, sku: p.sku, quantity: p.quantity, location: p.location });
    setEditId(p.id);
  };

  const handleDelete = async (id) => {
    await fetch(`${API}/${id}`, { method: 'DELETE' });
    fetchProducts();
  };

  return (
    <div style={{ maxWidth: 800, margin: '40px auto', fontFamily: 'sans-serif' }}>
      <h1>📦 Warehouse Management System</h1>

      <form onSubmit={handleSubmit} style={{ display: 'flex', gap: 8, marginBottom: 24, flexWrap: 'wrap' }}>
        <input placeholder="Name" value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} required />
        <input placeholder="SKU" value={form.sku} onChange={e => setForm({ ...form, sku: e.target.value })} required />
        <input placeholder="Quantity" type="number" value={form.quantity} onChange={e => setForm({ ...form, quantity: e.target.value })} required />
        <input placeholder="Location" value={form.location} onChange={e => setForm({ ...form, location: e.target.value })} />
        <button type="submit">{editId ? 'Update' : 'Add Product'}</button>
        {editId && <button type="button" onClick={() => { setEditId(null); setForm({ name: '', sku: '', quantity: '', location: '' }); }}>Cancel</button>}
      </form>

      <table border="1" cellPadding="8" style={{ width: '100%', borderCollapse: 'collapse' }}>
        <thead style={{ background: '#f0f0f0' }}>
          <tr>
            <th>ID</th><th>Name</th><th>SKU</th><th>Quantity</th><th>Location</th><th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {products.map(p => (
            <tr key={p.id}>
              <td>{p.id}</td>
              <td>{p.name}</td>
              <td>{p.sku}</td>
              <td>{p.quantity}</td>
              <td>{p.location}</td>
              <td>
                <button onClick={() => handleEdit(p)}>Edit</button>{' '}
                <button onClick={() => handleDelete(p.id)} style={{ color: 'red' }}>Delete</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
